import{_ as l,a0 as o,w as d,s as p,ao as r,I as n,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 上查找和刪除損壞的符號鏈接 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上查找和刪除損壞的符號鏈接 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上查找和刪除損壞的符號鏈接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上查找和刪除損壞的符號鏈接 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200529 How to find and remove broken symlinks on Linux","title":"如何在 Linux 上查找和刪除損壞的符號鏈接","tag":"202006","desc":""},"relativePath":"202006/20200529 How to find and remove broken symlinks on Linux.md","filePath":"[post].md"}'),h={name:"202006/20200529 How to find and remove broken symlinks on Linux.md"};function c(k,e,g,u,b,f){const i=o("Link");return d(),p("div",null,[e[15]||(e[15]=r(`<h1 id="如何在-linux-上查找和刪除損壞的符號鏈接" tabindex="-1">如何在 Linux 上查找和刪除損壞的符號鏈接 <a class="header-anchor" href="#如何在-linux-上查找和刪除損壞的符號鏈接" aria-label="Permalink to “如何在 Linux 上查找和刪除損壞的符號鏈接”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202006/09/095016y7ranx1tssxdsttd.jpg" alt=""></p><blockquote><p>符號鏈接是指向另一個文件的 Linux 文件。如果刪除了被引用的文件，符號鏈接會保留，但不會顯示有問題，除非你嘗試使用它。以下是查找和刪除指向文件已被刪除的符號鏈接的簡單方法。</p></blockquote><p><ruby>符號鏈接<rt>symbolic link</rt></ruby>在 Linux 系統上扮演了非常有用的角色。它們可以幫助你記住重要文件在系統上的位置，使你更容易訪問這些文件，並讓你不必為了更方便訪問大文件而複製它們，從而節省了大量的空間。</p><h3 id="什麼是符號鏈接" tabindex="-1">什麼是符號鏈接？ <a class="header-anchor" href="#什麼是符號鏈接" aria-label="Permalink to “什麼是符號鏈接？”">​</a></h3><p>通常稱它們為“符號鏈接”或“軟鏈接”，符號鏈接是非常小的文件。實際上，符號鏈接真正包含的是它指向的文件的名稱，通常包含路徑（相對於當前位置或絕對路徑）。如果有個名為 <code>ref1</code> 的文件指向名為 <code>/apps/refs/ref-2020</code> 的文件，那麼 <code>ref1</code> 的長度將為 19 個字符，即使 <code>ref-202</code> 文件有 2TB。如果指向 <code>./ref-2020</code>，那麼長度僅為 10 個字符。如果指向 <code>ref-2020</code>，那麼只有 8 個字節。</p><p>如果你執行 <code>vi ref1</code> 之類的命令（其中 <code>ref1</code> 是符號鏈接的名稱），你將編輯 <code>ref1</code> 指向的文件，而不是符號鏈接本身的內容。Linux 系統知道如何使用符號鏈接，並且可以做正確的事。同樣，如果你使用諸如 <code>cat</code>、<code>more</code>、<code>head</code> 或 <code>tail</code> 之類的命令，那麼將查看引用文件的內容。</p><p>另一方面，如果刪除符號鏈接，你將刪除該鏈接，而不是引用的文件。再説一次，Linux 知道怎麼做。符號鏈接使得使用和共享文件更加容易，僅此而已。</p><h4 id="符號鏈接損壞時" tabindex="-1">符號鏈接損壞時 <a class="header-anchor" href="#符號鏈接損壞時" aria-label="Permalink to “符號鏈接損壞時”">​</a></h4><p>當一個符號鏈接所指向的文件從系統中刪除或重新命名時，符號鏈接將不再起作用。符號鏈接只不過是存儲在某個特定目錄中的引用而已，它不會隨着指向它的文件發生變化而更新或刪除。它一直指向被引用的文件，即使這個文件早已消失。</p><p>如果你嘗試使用指向一個不存在的文件的符號鏈接，那麼將出現如下錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail whassup</span></span>
<span class="line"><span>tail: cannot open &#39;whassup&#39; for reading: No such file or directory</span></span></code></pre></div><p>如果你嘗試訪問指向自身的符號鏈接（是的，奇怪的事情發生了），你將看到類似以下的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat loopy</span></span>
<span class="line"><span>cat: loopy: Too many levels of symbolic links</span></span>
<span class="line"><span>$ ls -l loopy</span></span>
<span class="line"><span>lrwxrwxrwx 1 shs shs 5 May 28 18:07 loopy -&gt; loopy</span></span></code></pre></div><p>而且，如果（上面的）長列表的第一個字母沒有引起你的注意，這表示該文件是符號鏈接。<code>rwxrwxrwx</code> 權限是標準權限，並不反映符號鏈接指向的文件的權限。</p><h3 id="查找損壞的符號鏈接" tabindex="-1">查找損壞的符號鏈接 <a class="header-anchor" href="#查找損壞的符號鏈接" aria-label="Permalink to “查找損壞的符號鏈接”">​</a></h3><p><code>find</code> 命令有一個選項，能讓你找到指向不再存在的文件的符號鏈接。此命令列出當前目錄中的符號鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l</span></span></code></pre></div><p><code>l</code> （小寫字母 <code>L</code>）告訴 <code>find</code> 命令查找符號鏈接。</p><p>另一方面，下面的命令在當前目錄中查找指向<em>不存在</em>的文件的符號鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -xtype l</span></span></code></pre></div><p>為了避免在該命令嘗試查找你無權檢查的文件或目錄時發生錯誤，你可以將所有錯誤輸出到 <code>/dev/null</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -xtype l 2&gt;/dev/null</span></span></code></pre></div><p>你也可以使用此命令找到損壞的符號鏈接。它比前面的更長，但做的是同樣的事情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l ! -exec test -e {} \\; -print 2&gt;/dev/null</span></span></code></pre></div><h3 id="如何處理損壞的符號鏈接" tabindex="-1">如何處理損壞的符號鏈接 <a class="header-anchor" href="#如何處理損壞的符號鏈接" aria-label="Permalink to “如何處理損壞的符號鏈接”">​</a></h3><p>除非你知道符號鏈接引用的文件會被替換，否則最好的方法是直接刪除損壞的鏈接。實際上，如果需要，你可以使用一條命令查找並刪除損壞的符號鏈接，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -xtype l 2&gt;/dev/null -exec rm {} \\;</span></span></code></pre></div><p>該命令的 <code>rm {}</code> 部分會變成“刪除文件”的命令</p><p>如果你想將符號鏈接與不同的文件相關聯，你必須先刪除該符號鏈接，然後重新創建它，使其指向新文件。這是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm ref1</span></span>
<span class="line"><span>$ ln -s /apps/data/newfile ref1</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>符號鏈接使引用的文件更易於查找和使用，但有時它會比那些宣傳去年已經關閉的餐館的路標還過分。<code>find</code> 命令可以幫助你擺脱損壞的符號鏈接，或者提醒你沒有你可能仍然需要的文件。</p><hr>`,34)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.networkworld.com/article/3546252/how-to-find-and-remove-broken-symlinks-on-linux.html"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3546252/how-to-find-and-remove-broken-symlinks-on-linux.html",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),a(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const w=l(h,[["render",c]]);export{y as __pageData,w as default};
